create table if not exists gt_private.legacy_dan_directory_v5(dan_number text primary key, full_name text not null,source_rank text,source_file text not null,imported_at timestamptz not null default now());alter table gt_private.legacy_dan_directory_v5 enable row level security;revoke all on gt_private.legacy_dan_directory_v5 from public,anon,authenticated;
-- Directory rows imported through authenticated Drive connector from the verified source; personal names excluded from source control.

create or replace function gt_private.lookup_name_v5(p_name text) returns text language plpgsql security definer set search_path=pg_catalog as $$ declare n text:=regexp_replace(btrim(p_name),'\s+',' ','g');begin if length(n) not between 3 and 200 or position(' ' in n)=0 then raise exception 'FULL_NAME_REQUIRED';end if; if exists(select 1 from public.gt_athletes where regexp_replace(btrim(full_name),'\s+',' ','g')=n) or exists(select 1 from gt_private.legacy_dan_directory_v5 where regexp_replace(btrim(full_name),'\s+',' ','g')=n) then return 'found';end if;return 'not_found';end $$;
revoke all on function gt_private.lookup_name_v5(text) from public;grant usage on schema gt_private to anon;grant execute on function gt_private.lookup_name_v5(text) to anon,authenticated;
create or replace function public.gt_lookup_name_v5(p_name text) returns text language sql security invoker set search_path=pg_catalog as $$select gt_private.lookup_name_v5(p_name)$$;revoke all on function public.gt_lookup_name_v5(text) from public;grant execute on function public.gt_lookup_name_v5(text) to anon,authenticated;
create or replace function gt_private.prevent_legacy_duplicate_v5() returns trigger language plpgsql security definer set search_path=pg_catalog as $$begin if auth.uid() is not null and exists(select 1 from gt_private.legacy_dan_directory_v5 where regexp_replace(btrim(full_name),'\s+',' ','g')=regexp_replace(btrim(new.full_name),'\s+',' ','g')) then raise exception 'DUPLICATE_REVIEW_REQUIRED';end if;return new;end $$;revoke all on function gt_private.prevent_legacy_duplicate_v5() from public,anon,authenticated;create trigger gt_prevent_legacy_duplicate_v5 before insert on public.gt_athletes for each row execute function gt_private.prevent_legacy_duplicate_v5();
